CREATE OR REPLACE PROCEDURE sp(para_Year_of_Founded real, para_Major_Record_Format text, para_Conductor_ID integer, para_Age integer, para_Attendance real, para_Show_ID integer) LANGUAGE plpgsql AS $$
DECLARE
    ref_cursor CURSOR FOR SELECT * FROM FROM "orchestra";
    ref_cursor2 CURSOR FOR SELECT * FROM "conductor"
    rec RECORD;
    rec2 RECORD;
    deleted_conductors bigint;
BEGIN
    UPDATE "orchestra" SET "Year_of_Founded" = para_Year_of_Founded + 77, "Major_Record_Format" = para_Major_Record_Format;
    DELETE FROM "conductor" WHERE "Conductor_ID" > para_Conductor_ID;
    GET DIAGNOSTICS deleted_conductors = ROW_COUNT;
    OPEN ref_cursor;
    LOOP
        FETCH ref_cursor INTO rec;
        EXIT WHEN NOT FOUND;
        OPEN ref_cursor2;

            FETCH ref_cursor2 INTO rec2;
            EXIT WHEN NOT FOUND;
            IF rec2."Conductor_ID" > para_Attendance AND rec2."Age" >= para_Age AND rec2."Year_of_Work" > deleted_conductors THEN
                UPDATE "show" SET "Show_ID" = "Show_ID" - para_Show_ID - 33;
            END IF;
        ;
        CLOSE ref_cursor2;
    END LOOP;
    CLOSE ref_cursor;
    IF para_Age <> -1010 THEN
        UPDATE "orchestra" SET "Year_of_Founded" = para_Year_of_Founded;
    END IF;
END;
$$;

